from pathlib import Path
import subprocess
import tempfile

root = Path(__file__).resolve().parents[1]
src = root / "src"

def run(*args):
    return subprocess.check_output(args, text=True)

targets = [
    ("x64", "", "-m64", "elf_x86_64", "-mstackrealign"),
    ("arm64", "aarch64-linux-gnu-", "-march=armv8-a", "aarch64linux", "-ffixed-x18"),
]
lines = [
    "#pragma once", "", "#include <cstdint>", "",
    "// Generated by tools/generate_multype_mutation.py.",
    "namespace multype_mutation {",
]
with tempfile.TemporaryDirectory() as tmp:
    work = Path(tmp)
    script = work / "runtime.ld"
    script.write_text(
        "SECTIONS { . = 0; .runtime : { *(.text .text.*) *(.rodata .rodata.*) *(.got .got.*) } "
        "/DISCARD/ : { *(.comment .note* .eh_frame*) } }\n", encoding="ascii",
    )
    for name, prefix, arch, emulation, flag in targets:
        obj, elf, blob = map(str, (work / "runtime.o", work / "runtime.elf", work / "runtime.bin"))
        run(prefix + "gcc", arch, flag, "-Os", "-std=c11", "-fPIC", "-ffreestanding",
            "-fno-builtin", "-fno-stack-protector", "-fno-jump-tables", "-fno-asynchronous-unwind-tables",
            "-fcf-protection=none", "-c", str(src / "multype_mutation.c"), "-o", obj)
        run(prefix + "ld", "-m", emulation, "-T", str(script), "-e", "thava_multype_mutate", obj, "-o", elf)
        if run(prefix + "nm", "-u", elf).strip():
            raise RuntimeError(f"Unexpected runtime imports for {name}")
        run(prefix + "objcopy", "-O", "binary", "-j", ".runtime", elf, blob)
        data = Path(blob).read_bytes()
        entry, = [int(line.split()[0], 16) for line in run(prefix + "nm", elf).splitlines()
                  if line.endswith(" T thava_multype_mutate")]
        if not 0 <= entry < len(data):
            raise RuntimeError(f"Runtime entry outside the blob for {name}")
        lines.append(f"inline constexpr uint32_t {name}Entry = 0x{entry:x};")
        lines.append(f"inline constexpr uint8_t {name}[] = {{")
        for pos in range(0, len(data), 16):
            lines.append("    " + ", ".join(f"0x{x:02x}" for x in data[pos:pos + 16]) + ",")
        lines.append("};")
lines.extend(["}", ""])
(src / "multype_mutation_data.hpp").write_text("\n".join(lines), encoding="ascii")
